-- ──────────────────────────────────────────────────────────────────
-- apply-creator-triage.sql
--
-- Applies the triage from commit 3b8e03d to the 100 creator prospects that
-- ALREADY exist in public.creator_prospects.
--
--   PRIORITY 15 -> stage 'qualified'
--   BACKUP   10 -> stage 'identified'
--   REJECT   75 -> stage 'disqualified' + disqualified_reason
--
-- ONE TOP-LEVEL STATEMENT. The whole operation is a single DO block. An
-- earlier version used separate top-level statements with ON COMMIT DROP
-- temp tables; the Supabase SQL Editor changes transaction context between
-- statements, so the temp tables vanished before the next statement ran and
-- it failed with 42P01 "relation _tri does not exist". Everything now lives
-- inside one statement, so there is no boundary for the tables to fall
-- through. There is no ON COMMIT DROP anywhere; both temp tables are dropped
-- explicitly at the end of the block.
--
-- A DO block is atomic: any RAISE EXCEPTION rolls back every change made
-- inside it, including the UPDATE and the temp tables.
--
-- WHAT IT TOUCHES: score, stage, disqualified_reason, notes, follow_up_at,
-- email, profile_url, niche, location, updated_at - on matched rows only.
-- It INSERTS nothing into creator_prospects, DELETES nothing, and creates no
-- permanent object and no schema.
--
-- FOLLOW-UP PRIORITY: creator_prospects has no `priority` column and none is
-- added. Priority rides on the existing follow_up_at column:
--   PRIORITY -> 2026-07-27 (act first)   BACKUP -> 2026-08-10   REJECT -> null
-- so `order by follow_up_at nulls last, score desc` gives the working order.
--
-- MATCHING, strongest identifier first:
--   1. normalised profile_url (scheme, www., query/fragment and trailing
--      slashes stripped, lowercased) - inline regexp_replace, no function
--      is created
--   2. platform + normalised platform_handle
--   3. lowercased email - SECONDARY CHECK ONLY, never the sole key
--
-- IDEMPOTENT: re-running writes the same literal values to the same rows.
-- The block drops any leftover temp tables before it starts, so a re-run in
-- the same session is clean.
--
-- OUTPUT: a single statement cannot return result sets, so every count is
-- reported via RAISE NOTICE. Read them in the Supabase "Messages"/notices
-- pane. Verification SELECTs to run afterwards are at the bottom of this
-- file, commented out.
-- ──────────────────────────────────────────────────────────────────

do $triage$
declare
  n_rows     integer;
  n_matched  integer;
  n_distinct integer;
  n_updated  integer;
  n_qual     integer;
  n_ident    integer;
  n_disq     integer;
  missing    text;
begin
  -- Idempotency: clear anything left by a previous run in this session.
  drop table if exists _tri;
  drop table if exists _match;

  create temporary table _tri (
    name      text primary key,
    url       text,
    platform  text,
    handle    text,
    email     text,
    niche     text,
    location  text,
    score     integer,
    stage     text,
    reason    text,
    follow_up timestamptz,
    notes     text
  );

  insert into _tri
    (name, url, platform, handle, email, niche, location, score, stage, reason, follow_up, notes)
  values
    ('bakka cosplay', 'https://www.bakkacosplay.com/commissions', 'other', 'bakkacosplay', 'contact@bakkaCosplay.com', 'cosplay', NULL, 98, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the maker-owned website. Page identifies Florence Heyer, operating as bakka cosplay since 2005. CONTACTABLE - contact@bakkaCosplay.com published in plain text. MONETIZATION: wig, beard, prop and costume commissions with example pricing of roughly EUR 690-1270 and bookable commission slots. CRUCIALLY she already runs Patreon, Ko-fi, an Amazon wishlist, PayPal and Twitch alongside the commissions - six separate money surfaces, which is the exact sprawl Spotlightly exists to collapse. SOCIALS: Instagram, TikTok, Twitter, Facebook, Pinterest, Twitch, YouTube. FOLLOWERS: not published. SOURCE: https://www.bakkacosplay.com/commissions. REVIEW FLAG: EU-based (pricing in EUR) - confirm Stripe Connect coverage. FIT: the single best structural match found - memberships, tips, wishlist, commissions and live all already in use, just scattered. OPENER: Patreon, Ko-fi, a wishlist, PayPal and Twitch is five places for people to pay you, and a commission queue on top. TRIAGE 2026-07-26: PRIORITY (score 98 = niche 20 + activity 18 + contact 20 + monetization 20 + independent 10 + quality 10). Re-verified 2026-07-26: copyright reads (c) 2026 bakka cosplay | Florence Heyer FX, and contact@bakkaCosplay.com is still published in several places. Confirmed a SOLE PROPRIETOR, not a company. Monetization is the broadest verified anywhere in this bank: commissions at roughly EUR 690-1270 with bookable slots, running alongside Patreon, Ko-fi, an Amazon wishlist, PayPal and Twitch. MISSING: follower counts. PRIORITY - top of the list because five separate revenue streams are already running on five separate platforms, which is exactly the consolidation Spotlightly sells.'),
    ('Christina Persika', 'https://persikadesignco.com/tattoo-tickets', 'other', 'persikadesignco', 'christina@persikadesignco.com', 'tattoo', 'Milwaukee, WI, USA', 96, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the artist-owned website. CONTACTABLE - christina@persikadesignco.com published in plain text. Operating as Persika Design Co since 2016. MONETIZATION: sliding-scale tattoo tickets from USD 30 to 120 - an unusually thoughtful pricing model - plus art prints, greeting cards, notepads, stickers, gift cards, murals and custom design work. CREATES: watercolour, gouache, acrylic and digital art, tattoo flash, stationery and paper goods. SOCIALS: Instagram @persikadesignco, YouTube @christinapersika, Substack christinapersika, Facebook. FOLLOWERS: not published. SOURCE: https://persikadesignco.com/tattoo-tickets. FIT: sells physical goods, digital flash and services, and already writes on Substack - merch, digital products, paid posts and subscriptions all apply. OPENER: Sliding-scale tickets, prints and a Substack are three audiences that could be one. TRIAGE 2026-07-26: PRIORITY (score 96 = niche 18 + activity 18 + contact 20 + monetization 20 + independent 10 + quality 10). Re-verified 2026-07-26: copyright reads (c)2026, storefront is live with working cart, and christina@persikadesignco.com is still published with the Milwaukee address. Confirmed SOLO - no staff mentioned anywhere. Monetization: sliding-scale tattoo tickets from USD 30-120 plus prints, stationery, stickers, gift cards, murals and custom design. MISSING: follower counts. PRIORITY - sliding-scale pricing shows she already thinks in tiers, which maps directly onto Spotlightly subscription tiers.'),
    ('CosPayton', 'https://cospayton.com/pages/commissions', 'other', 'cospayton', 'cospayton@gmail.com', 'cosplay', NULL, 96, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the creator-owned website. CONTACTABLE - email published in plain text on the commissions page. MONETIZATION: unusually broad - sewing patterns, embroidered patches, prop blueprints and SVG files, 3D models and kits, custom fabric, plus scheduled commission windows (page states commissions last opened 1-5 June 2026). SOCIALS: Instagram @cospayton, YouTube @CosPayton, TikTok @cospayton, Twitter @cospayton. FOLLOWERS: not published. SOURCE: https://cospayton.com/pages/commissions. FIT: sells four distinct digital product lines plus commissions - the closest match found to Spotlightly digital products, merch and paid posts together. OPENER: Patterns, patches, blueprints and 3D kits are four product lines - they should not need four checkouts. TRIAGE 2026-07-26: PRIORITY (score 96 = niche 20 + activity 18 + contact 20 + monetization 20 + independent 10 + quality 8). Re-verified 2026-07-26: page states the last commission window ran 1-5 June 2026 - inside the 90-day activity bar - and cospayton@gmail.com is still published. Creator describes herself as "only one person", confirming an individual. Monetization: sewing patterns, embroidered patches, prop blueprints, SVG files, 3D models and kits, custom fabric, plus scheduled commission windows. MISSING: follower counts, location. PRIORITY - a digital catalogue plus timed commission drops is the single best fit for paid posts and digital products.'),
    ('Javier Gonzalez', 'https://www.solostreetworkout.com/en/personalized-calisthenics-program/', 'other', 'javossj4', 'info@solostreetworkout.com', 'fitness', NULL, 96, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the coach-owned website. CONTACTABLE - info@solostreetworkout.com published in plain text. MONETIZATION: Elite Coaching at USD 89/month, including a personalised programme, direct email Q&A and an on-demand content folder. Page describes him as a certified IFBB-backed international coach. SOCIALS: Instagram @javossj4, YouTube, WhatsApp. FOLLOWERS: not published. SOURCE: https://www.solostreetworkout.com/en/personalized-calisthenics-program/. FIT: already sells recurring access plus direct messaging and a gated content library - close to a one-for-one map onto Spotlightly subscriptions, messaging and paid posts. OPENER: You are already selling a subscription with direct access and a private library - the only question is who takes a cut of it. TRIAGE 2026-07-26: PRIORITY (score 96 = niche 20 + activity 20 + contact 20 + monetization 18 + independent 10 + quality 8). Re-verified 2026-07-26: page footer reads "Last modified on July 20, 2026" - SIX DAYS before review, the strongest recency signal in the whole bank. info@solostreetworkout.com still published. Individual coach (IFBB-backed), not a company. Monetization: personalised calisthenics at USD 89/month with an active summer promotion ending 21 September. MISSING: follower counts, location. PRIORITY - verifiably active this month and already selling a recurring subscription.'),
    ('Carrie Welling', 'https://www.patreon.com/carriewelling/about', 'patreon', 'carriewelling', 'carriewellingbooking@gmail.com', 'music', 'Nashville, TN, USA', 95, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: 244 members (154 paid) - 63% conversion. ACTIVITY: 439 posts, exclusive music, demos, livestreams and listening parties. SOCIALS: Instagram @carriewellingmusic, Twitter @wellomusic. FOLLOWERS: not published. EMAIL: not obtainable. SOURCE: https://www.patreon.com/carriewelling/about. FIT: livestreams plus paid archive - live, subscriptions and tips all apply. OPENER: Listening parties and livestreams are live events - they deserve better than a members-only post. CONTACT UPDATE 2026-07-25: carriewellingbooking@gmail.com verified by fetching https://www.carriewelling.com/ - a dedicated BOOKING address she publishes herself, no agency in between. Same page confirms Patreon (fans called Wellos), a merch store, a virtual tip jar and the album Crack in the Chaos - four revenue lines, all self-run. NOTE: that page does not itself state a home city; the Nashville location in this row came from the Patreon source cited above, and the site only says Nashville musicians played on the album - worth confirming before use. TRIAGE 2026-07-26: PRIORITY (score 95 = niche 20 + activity 17 + contact 20 + monetization 19 + independent 10 + quality 9). Re-verified 2026-07-26: 244 members of whom 154 are PAID (63% conversion, unusually high) across 439 posts. Location confirmed as Nashville, Tennessee on the page itself, which validates the recorded field. Solo singer-songwriter. carriewellingbooking@gmail.com is a dedicated booking address she publishes on her own site. MISSING: exact last-post date. PRIORITY - livestreams, demos and listening parties are subscriptions, tips and paid posts already.'),
    ('Fitness with PJ', 'https://www.patreon.com/fitnesswithpj', 'patreon', 'fitnesswithpj', 'pj@fitnesswithpj.com', 'fitness', NULL, 95, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: 522 paid members at $15/month minimum - the strongest verified paid base per member in this list. NICHE: fitness for women over 40. SOCIALS: Instagram, YouTube, Facebook. FOLLOWERS: not published. EMAIL: not obtainable. SOURCE: https://www.patreon.com/fitnesswithpj. FIT: high-value recurring subscribers and a clearly defined audience. OPENER: 522 people at $15 is a real business - the question is only how much of it the platform keeps. CONTACT UPDATE 2026-07-25: pj@fitnesswithpj.com verified by fetching https://www.fitnesswithpj.com/contact-with-fitness-with-pj-over-40-fitness/ - published in plain text for coaching enquiries. Same page links back to patreon.com/fitnesswithpj, which confirms this site and the Patreon row are the same person. Audience stated as women over 40; sells app-based training, merch and equipment. TRIAGE 2026-07-26: PRIORITY (score 95 = niche 20 + activity 16 + contact 20 + monetization 20 + independent 10 + quality 9). Re-verified 2026-07-26: Patreon still shows 522 PAID members starting at USD 15/month - the largest verified paid base in this bank, roughly USD 7,800/month gross. Individual creator serving women over 40. pj@fitnesswithpj.com confirmed on her own site, which links back to this same Patreon. MISSING: exact date of last post (Patreon does not expose it), follower counts, location. PRIORITY - the single clearest revenue case here; a platform fee change is money she can count.'),
    ('PlexiCosplay', 'https://www.plexicosplay.com/', 'other', 'plexicosplay', 'plexicosplay@gmail.com', 'cosplay', 'Maryland, USA', 94, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the creator-owned website. Creator first name Candace per site. CONTACTABLE - plexicosplay@gmail.com published in plain text for convention guest inquiries (the site also references a second address, plexi@ciberdime.com). MONETIZATION: own online shop selling handcrafted costumes and custom patterns, affiliate partnerships (CoscomCosplay, DecoArt, Worbla), paid convention appearances, and sponsored collaborations named on the page with Netflix, Blizzard Entertainment, Ubisoft, Digital Extremes and Nexon Korea. ACTIVITY: confirmed upcoming appearances at C2E2 March 2026, TennoCon July 2026 and Dragon Con 2026; YouTube tutorials; contributor to BERNINA and CanvasRebel; cited in a Forbes article October 2024. SOCIALS: YouTube @PlexiCosplay, Instagram, TikTok, Facebook, Twitter. FOLLOWERS: not published. SOURCE: https://www.plexicosplay.com/. FIT: highest-scoring prospect found - contactable, self-managed, sells patterns and costumes, takes paid bookings, and already commands brand sponsorships. Digital products, merch, subscriptions and messaging all apply. OPENER: You are selling patterns, taking convention bookings and running brand collaborations off three different systems - one page could hold all of it. TRIAGE 2026-07-26: PRIORITY (score 94 = niche 20 + activity 20 + contact 18 + monetization 18 + independent 8 + quality 10). Re-verified 2026-07-26: site lists 2026 convention appearances including C2E2 (March 2026), TennoCon (July 2026) and Dragon Con 2026 - active THIS MONTH. Individual, Candace Birger. Monetization: own shop for handcrafted costumes and patterns, affiliate partnerships (CoscomCosplay, DecoArt, Worbla) and paid convention appearances. CONTACT CAVEAT: two addresses are published, plexicosplay@gmail.com and plexi@ciberdime.com; the first is hers and is the one recorded. The ciberdime domain appears to be a third party, which is why the independence score is not full marks. PRIORITY.'),
    ('Ink By Faye', 'https://www.inkbyfaye.com/f-a-q/', 'other', 'inkbyfaye', 'inkbyfaye@gmail.com', 'tattoo', 'Concord, USA', 93, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the artist-owned website. CONTACTABLE - inkbyfaye@gmail.com published in plain text. MONETIZATION: USD 50 non-refundable consultation fee, USD 150 non-refundable deposit, hourly rates for custom work with discounted rates for flash, one-hour minimum - a fully priced service ladder. DEMAND SIGNAL: page states she is booked two to four months in advance. STYLE: neo-traditional and whimsical - fantasy, creatures, pinups, Disney, Pixar, anime, video games. Works as an independent contractor, tattooing Saturdays. SOCIALS: Instagram @inkbyfaye. FOLLOWERS: not published. SOURCE: https://www.inkbyfaye.com/f-a-q/. FIT: already charges consultation fees and deposits by hand - Spotlightly would automate the deposit and let flash sell itself. OPENER: Booked four months out while collecting deposits manually is a scheduling problem, not a demand problem. TRIAGE 2026-07-26: PRIORITY (score 93 = niche 20 + activity 16 + contact 20 + monetization 18 + independent 10 + quality 9). Re-verified 2026-07-26: inkbyfaye@gmail.com still published and the page confirms an INDEPENDENT CONTRACTOR working solo, tattooing Saturdays in a shared space in Concord. Monetization is a full priced ladder: USD 50 consultation, USD 150 deposit, hourly custom rates with discounted flash, one-hour minimum. DEMAND: booked two to four months ahead. MISSING: no explicit 2026 date on the page, so recency rests on the booking-lead statement rather than a timestamp. PRIORITY.'),
    ('Michelle Valadon', 'https://michellevaladon.com/pages/custom', 'other', 'michellevaladondesign', 'michelle@michellevaladon.com', 'alternative fashion', 'USA', 93, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the maker-owned website. CONTACTABLE - michelle@michellevaladon.com published in plain text. CREATES: custom vintage-inspired and gothic jewellery - rings, necklaces, bracelets, earrings - plus modifications to existing pieces and bespoke one-of-a-kind commissions. MONETIZATION: e-commerce sales plus bespoke commissions taken on a 50% non-refundable deposit. Page reads first-person with a Meet the Designer section. SOCIALS: Instagram @michellevaladondesign, Facebook, Pinterest. FOLLOWERS: not published. SOURCE: https://michellevaladon.com/pages/custom. FIT: already takes deposits on bespoke work - commissions, merch and messaging. OPENER: Taking 50% deposits on bespoke pieces by email is a checkout waiting to happen. TRIAGE 2026-07-26: PRIORITY (score 93 = niche 18 + activity 18 + contact 20 + monetization 18 + independent 9 + quality 10). Re-verified 2026-07-26: copyright reads (c) 2026 Michelle Valadon and michelle@michellevaladon.com is still published in both footer and contact sections. Individual maker - first-person throughout with a "Meet the Designer" section, though she works with a network of stone dealers, casters and setters. Monetization: e-commerce plus bespoke commissions on a 50% non-refundable deposit. MISSING: follower counts, city. PRIORITY.'),
    ('TIFFY', 'https://tiffy.bandcamp.com/', 'other', 'tiffyallcaps', 'telltiffy@gmail.com', 'music', 'Somerville, MA, USA', 91, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching BOTH the Bandcamp profile and the artist website tiffymusic.com. CONTACTABLE - booking/contact email published in plain text by the artist on her own Bandcamp profile and confirmed on her own site. MONETIZATION: music sales on Bandcamp plus merch - the I Wanted To Know EP cassette is on pre-order with bonus tracks. ACTIVITY: recent releases IRB featuring Sad13, Scam Likely, and The Sign. SOCIALS: Instagram @tiffyallcaps, Facebook, TikTok, YouTube, Bluesky, plus Spotify/Apple/Tidal/SoundCloud. FOLLOWERS: not published. SOURCES: https://tiffy.bandcamp.com/ ; https://tiffymusic.com/. FIT: self-releasing, sells physical merch, active release schedule, owns a domain - subscriptions, tips and merch all apply. OPENER: Pre-orders for a cassette run are exactly the moment a direct fan page earns its keep. TRIAGE 2026-07-26: PRIORITY (score 91 = niche 20 + activity 16 + contact 20 + monetization 16 + independent 10 + quality 9). Re-verified 2026-07-26: Bandcamp lists "Rndm Coverz (2020 - 2026)", confirming activity into 2026, and telltiffy@gmail.com remains published in plain text. Confirmed SOLO artist - Tiffany Sammy, multi-instrumentalist. Monetization: Bandcamp sales plus an I Wanted To Know EP cassette on pre-order with bonus tracks. MISSING: individual release dates are not shown; follower counts. PRIORITY - pre-orders and physical merch on an owned audience.'),
    ('Emma-Lee Moss', 'https://www.patreon.com/emmaleemoss', 'patreon', 'emmaleemoss', 'emmythegreat@gmail.com', 'music', NULL, 89, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: tiers from $7.50/month. ACTIVITY: latest post 16 hours before verification - the most recently active creator found. CONTENT: unreleased demos, archive material, current songwriting, Song Circle community. FOLLOWERS: not published. Member count not shown. EMAIL: not obtainable. SOURCE: https://www.patreon.com/emmaleemoss. FIT: archive plus community - paid posts and messaging. OPENER: Posting voice notes on a Saturday morning is the kind of thing fans pay for - it should not be buried in a feed you rent. CONTACT UPDATE 2026-07-25: emmythegreat@gmail.com verified by fetching https://www.emmaleemoss.com/about - published for management enquiries, written with spaces around the @ as light anti-harvesting, so it is human-readable and deliberately published rather than obfuscated beyond reading. REVIEW FLAG: she also lists a live booking agent (Runway Artists) and a literary agent (David Higham), so she is agency-represented, not self-managed. Four albums as Emmy the Great; based in Hong Kong; sells albums, shop items and songwriting courses. TRIAGE 2026-07-26: PRIORITY (score 89 = niche 20 + activity 20 + contact 18 + monetization 16 + independent 6 + quality 9). Re-verified 2026-07-26: most recent Patreon post was YESTERDAY (a Saturday morning voice note) - the most recently active creator in this bank. Confirmed solo; eighteen years as Emmy the Great before moving to her own name in 2022. Tiers from USD 7.50/month; Song Circle community. CONTACT: emmythegreat@gmail.com is published on her own site for management enquiries. INDEPENDENCE PENALTY: she lists a live booking agent (Runway Artists) and a literary agent (David Higham), so she is NOT self-managed - this is the main thing holding the score down. MISSING: member count. PRIORITY on activity and fit.'),
    ('Gavin Maxwell', 'https://www.gavin.fit/', 'other', 'gavin.motion', 'info@gavin.fit', 'fitness', 'Los Angeles, CA, USA', 89, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the coach-owned website. CONTACTABLE - info@gavin.fit published in plain text on his own site. MONETIZATION: personalised calisthenics programming, nutrition coaching, educational ebooks and workshops - a product ladder rather than a single service. Pricing not shown on the page. SOCIALS: Instagram @gavin.motion, YouTube @Gavin.Motion, TikTok @gavin.motion, plus a Facebook coaching group. FOLLOWERS: not published. SOURCE: https://www.gavin.fit/. FIT: sells ebooks and workshops alongside 1-to-1 coaching, so digital products, subscriptions and messaging all apply; the Facebook group suggests a community he does not own. OPENER: Ebooks, workshops and coaching are three products, and the community holding them together lives on Facebook. TRIAGE 2026-07-26: PRIORITY (score 89 = niche 20 + activity 14 + contact 20 + monetization 16 + independent 10 + quality 9). Re-verified 2026-07-26: info@gavin.fit still published in the footer; individual coach, not a multi-coach company. Monetization: personalised calisthenics programming, nutrition coaching, ebooks and workshops - a real product ladder rather than one service. ACTIVITY CAVEAT: newest dated item is a May 2025 testimonial and there is no copyright year, so recency is weaker than the others in this tier. MISSING: prices (application-based), follower counts. PRIORITY, lowest confidence on recency.'),
    ('GiveWave Studios', 'https://givewavestudios.com/commission-request/', 'other', 'givewavestudios', 'givewave.studios@gmail.com', 'cosplay', 'Lowell, MA, USA', 89, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the maker-owned website. CONTACTABLE - givewave.studios@gmail.com published in plain text. MONETIZATION: unusually complete - commission work on a 50% non-refundable deposit with the balance before shipping, plus a retail shop selling finished props, DIY kits, apparel, accessories and patterns, plus an Etsy presence. Business address published on the site: 47 Lee St, Lowell MA 01852. SOCIALS: Instagram, Facebook, Twitter, YouTube, Twitch, Etsy. FOLLOWERS: not published. SOURCE: https://givewavestudios.com/commission-request/. FIT: deposits, digital patterns, physical merch and streaming all in one operation - close to the full Spotlightly surface area. REVIEW FLAG: the page does not state whether this is one person or a team. OPENER: Deposits, kits, patterns and a Twitch channel are four revenue lines running on four different tools. TRIAGE 2026-07-26: PRIORITY (score 89 = niche 20 + activity 14 + contact 20 + monetization 18 + independent 10 + quality 7). Re-verified 2026-07-26: givewave.studios@gmail.com still published and commissions are OPEN with a stated 7-business-day response. Confirmed one person - first-person singular throughout, described as a multi-disciplinary designer, no staff named. Monetization: commissions on 50% deposit plus a retail shop of finished props, DIY kits, apparel, accessories and patterns, plus Etsy. ACTIVITY CAVEAT: the copyright still reads 2018, so the site is stale even though the commission process is live - recency is inferred from the open queue, not a timestamp. PRIORITY, but verify he is still taking work before contact.'),
    ('Mugiwara Cosplay', 'https://www.patreon.com/mugiwaracosplay', 'patreon', 'mugiwaracosplay', 'mugiwarascreativecorner@gmail.com', 'cosplay', NULL, 86, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: 901 Patreon members, tiers from $1.50/month. SOCIALS: Twitter, Instagram (handles not displayed). FOLLOWERS: not published. EMAIL: not obtainable. SOURCE: https://www.patreon.com/mugiwaracosplay. FIT: sizeable paying membership already - subscriptions plus paid posts map directly. OPENER: 901 people already pay to follow your builds - that audience would carry straight over to a page you own. CONTACT UPDATE 2026-07-25: mugiwarascreativecorner@gmail.com verified by fetching https://mcreativecorner.com/about-2/contact/. Page confirms a ONE-PERSON fursuit and cosplay crafting studio in Germany - matches your self-managed preference. Sells fursuits, mascot costumes, creature cosplays, 3D print files, sewing patterns and premade suits, plus tutorials: physical commissions and digital products side by side. TRIAGE 2026-07-26: PRIORITY (score 86 = niche 20 + activity 15 + contact 20 + monetization 14 + independent 9 + quality 8). Re-verified 2026-07-26: 901 members and 812 posts, tiers from USD 1.50/month. IMPORTANT CORRECTION: stated earnings are USD 134.5/month, so despite 901 members the paying base is small and mostly free - the earlier note implying a sizeable paying membership overstated it. Own contact page confirms a ONE-PERSON fursuit and cosplay studio in Germany. mugiwarascreativecorner@gmail.com verified there. Sells fursuits, mascot costumes, 3D print files, sewing patterns and premades. MISSING: last-post date, paid-member split. PRIORITY - large audience, weak monetization, which is the profile most likely to switch.'),
    ('Julia Braun (Morph Studio)', 'https://morphstudio.eu/en/', 'other', 'morphstudio.eu', 'info@morphstudio.eu', 'alternative fashion', 'Berlin, Germany', 85, 'qualified', NULL, '2026-07-27'::timestamptz, 'VERIFIED 2026-07-25 by fetching the maker-owned website. CONTACTABLE - info@morphstudio.eu published in plain text. Page identifies Julia Braun as a master tailor and fashion designer working as an individual maker. CREATES: bespoke designer latex fashion, handcrafted to measure. MONETIZATION: shop sales plus custom commissions; pricing not shown. Business address published: Karl-Marx-Strasse 95, D-12043 Berlin, with a note that the studio recently moved from Hamburg. SOCIALS: Instagram @morphstudio.eu. FOLLOWERS: not published. SOURCE: https://morphstudio.eu/en/. REVIEW FLAG: Germany-based - confirm Stripe Connect coverage. FIT: made-to-measure commissions plus a shop, run by one named craftsperson - commissions, merch and messaging. OPENER: Made-to-measure work is a conversation before it is a sale, and that conversation is currently happening in your inbox. TRIAGE 2026-07-26: PRIORITY (score 85 = niche 18 + activity 14 + contact 20 + monetization 16 + independent 8 + quality 9). Re-verified 2026-07-26: info@morphstudio.eu still published; Julia Braun named as the master tailor designing every piece in Berlin. INDEPENDENCE CAVEAT: an extensive credits section names photographers, web designers and social media support, so she works with a network rather than entirely alone. ACTIVITY: no year on the copyright and no dated content - recency UNCONFIRMED. BACKUP - scores above the band on merit and would be PRIORITY if a slot were free; held back only by unconfirmed recency and the 15-slot cap.'),
