    ('Black Tattoo Studio', 'https://www.patreon.com/blktattoo', 'patreon', 'blktattoo', NULL, 'tattoo', NULL, 25, 'disqualified', 'No verified public business contact method', null, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: 17 members, tiers from $1/month - very early. SOCIALS: Facebook, Instagram, YouTube. FOLLOWERS: not published. EMAIL: not obtainable. SOURCE: https://www.patreon.com/blktattoo. REVIEW FLAG: studio rather than individual, and minimal traction. LOW PRIORITY. OPENER: Seventeen members is the start of something - worth building it somewhere you own. TRIAGE 2026-07-26: REJECT. No verified public business contact method could be found on any page this creator publishes, so there is no compliant way to reach them and both PRIORITY and BACKUP are out of reach. Everything previously verified about this prospect stands and is retained above; only the contact gap disqualifies them. Re-review immediately if a published business address is found.'),
    ('Dizzikat', 'https://www.patreon.com/dizzikat', 'patreon', 'dizzikat', NULL, 'tattoo', NULL, 25, 'disqualified', 'No verified public business contact method', null, 'VERIFIED 2026-07-25 by fetching profile. MONETIZATION: 14 members, tiers from $3/month. CONTENT: art and blogs, adjacent to tattoo/body art rather than core. SOCIALS: Instagram, Twitch, Twitter. FOLLOWERS: not published. EMAIL: not obtainable. SOURCE: https://www.patreon.com/dizzikat. REVIEW FLAG: small and niche-adjacent. LOW PRIORITY. OPENER: Small paid audiences are easier to move than big free ones. TRIAGE 2026-07-26: REJECT. No verified public business contact method could be found on any page this creator publishes, so there is no compliant way to reach them and both PRIORITY and BACKUP are out of reach. Everything previously verified about this prospect stands and is retained above; only the contact gap disqualifies them. Re-review immediately if a published business address is found.');

  -- ── Resolve each triage row to exactly one existing prospect ────────
  create temporary table _match as
  with p as (
    select id,
           platform,
           regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(profile_url,'')), '^https?://', ''), '^www\.', ''), '[?#].*$', ''), '/+$', '') as nurl,
           lower(coalesce(platform_handle,'')) as nhandle,
           lower(coalesce(email,''))           as nemail
      from public.creator_prospects
  ), t as (
    select name,
           regexp_replace(regexp_replace(regexp_replace(regexp_replace(lower(coalesce(url,'')), '^https?://', ''), '^www\.', ''), '[?#].*$', ''), '/+$', '') as nurl,
           platform,
           lower(coalesce(handle,'')) as nhandle,
           lower(coalesce(email,''))  as nemail
      from _tri
  )
  select distinct on (t.name)
         t.name,
         p.id,
         case when t.nurl <> '' and t.nurl = p.nurl                              then 'profile_url'
              when t.platform is not distinct from p.platform
               and t.nhandle <> '' and t.nhandle = p.nhandle                     then 'platform+handle'
              else 'email' end as matched_by
    from t
    join p
      on (t.nurl <> '' and t.nurl = p.nurl)
      or (t.platform is not distinct from p.platform and t.nhandle <> '' and t.nhandle = p.nhandle)
      or (t.nemail <> '' and t.nemail = p.nemail)
   order by t.name,
            case when t.nurl <> '' and t.nurl = p.nurl                           then 1
                 when t.platform is not distinct from p.platform
                  and t.nhandle <> '' and t.nhandle = p.nhandle                  then 2
                 else 3 end,
            p.id;

  -- ── Preflight. Any failure raises, which rolls the whole block back. ─
  select count(*) into n_rows from _tri;
  if n_rows <> 100 then
    raise exception 'PREFLIGHT FAILED: expected 100 triage rows, loaded %', n_rows;
  end if;
  raise notice 'triage rows loaded: % of 100', n_rows;

  select count(*) into n_matched from _match;
  if n_matched <> 100 then
    select string_agg(name, ', ' order by name) into missing
      from _tri where name not in (select name from _match);
    raise exception 'PREFLIGHT FAILED: matched % of 100 prospects. UNMATCHED: %',
      n_matched, coalesce(missing, '(none)');
  end if;
  raise notice 'matched: % of 100 prospects', n_matched;

  select count(distinct id) into n_distinct from _match;
  if n_distinct <> 100 then
    raise exception
      'PREFLIGHT FAILED: 100 triage rows collapsed onto % distinct prospects - ambiguous match',
      n_distinct;
  end if;
  raise notice 'distinct prospect ids: % of 100', n_distinct;

  -- ── The update. Matched rows only. No insert, no delete. ────────────
  update public.creator_prospects cp
     set score               = t.score,
         stage               = t.stage,
         disqualified_reason = nullif(t.reason, ''),
         notes               = t.notes,
         follow_up_at        = t.follow_up,
         email               = coalesce(nullif(t.email, ''),    cp.email),
         profile_url         = coalesce(nullif(t.url, ''),      cp.profile_url),
         niche               = coalesce(nullif(t.niche, ''),    cp.niche),
         location            = coalesce(nullif(t.location, ''), cp.location),
         updated_at          = now()
    from _tri t
    join _match m on m.name = t.name
   where cp.id = m.id;

  get diagnostics n_updated = row_count;
  if n_updated <> 100 then
    raise exception 'UPDATE FAILED: touched % rows, expected 100', n_updated;
  end if;
  raise notice 'rows updated: %', n_updated;

  -- ── Post-update verification of the final split. ────────────────────
  select count(*) filter (where stage = 'qualified'),
         count(*) filter (where stage = 'identified'),
         count(*) filter (where stage = 'disqualified')
    into n_qual, n_ident, n_disq
    from public.creator_prospects
   where id in (select id from _match);

  raise notice 'qualified  (PRIORITY): %', n_qual;
  raise notice 'identified (BACKUP):   %', n_ident;
  raise notice 'disqualified (REJECT): %', n_disq;

  if n_qual <> 15 or n_ident <> 10 or n_disq <> 75 then
    raise exception
      'VERIFY FAILED: expected 15/10/75, got %/%/% - everything rolled back',
      n_qual, n_ident, n_disq;
  end if;

  -- ── Explicit cleanup. No ON COMMIT DROP is used anywhere. ───────────
  drop table _tri;
  drop table _match;

  raise notice 'TRIAGE APPLIED: 15 PRIORITY / 10 BACKUP / 75 REJECTED. Nothing inserted or deleted.';
end
$triage$;

